<template>
 <section class="refund-goods" v-loading="loading||busy">
  <div class="heading"><div><h3>本退款退回与包裹</h3><p class="hint">购买商品与赠品分组查看，以下数量仅属于当前退款。退款商品、已确认实收和库存入账分别跟踪；整个合包的仓库回传请进入包裹详情查看。</p></div><el-button v-hasPermi="['order:refund:goods']" size="small" @click="refresh">刷新本退款货物进度</el-button></div>
  <el-alert v-if="error" :title="error" type="warning" :closable="false" />
  <div v-if="refund.return_auto" class="auto-return-status"><el-alert :title="autoCreateTitle" :description="refund.return_auto.message || '后台核对原发货来源、申请数量和退回仓后创建安排。'" :type="refund.return_auto.state==='MANUAL'?'warning':'info'" :closable="false" show-icon/><el-button v-if="['MANUAL','RETRY','CANCELED'].includes(refund.return_auto.state)&&refund.review_state==='APPROVED'&&refund.goods_state!=='DONE'" v-hasPermi="['order:refund:goods']" size="small" :loading="busy" @click="retryAutoCreate">重新检查并自动创建</el-button></div>
  <div class="toolbar"><el-tag :type="plans.some(planPending)?'warning':'info'">{{ plans.some(planPending)?'实收待分配':label(refund.goods_state) }}</el-tag>
    <template v-if="refund.review_state==='APPROVED'&&refund.goods_state!=='DONE'&&(refund.platform.platform_status!=='CLOSED'||refund.funds_state==='SUCCESS')">
      <el-button v-if="refund.goods_action==='CANCEL'" v-hasPermi="['order:refund:goods']" size="small" type="primary" @click="open('cancelUnshipped')">执行已审核未发取消</el-button>
      <el-button v-if="returnRequired" v-hasPermi="['order:refund:goods']" size="small" :type="refund.goods_state==='WAIT_QC'?'default':'primary'" @click="open('create')">创建退回安排</el-button>
      <el-button v-if="plans.length" v-hasPermi="['order:refund:goods']" size="small" :type="refund.goods_state==='WAIT_QC'?'primary':'default'" @click="open('finish')">确认货物处理完成</el-button>
    </template>
    <el-popover placement="bottom-start" trigger="click" width="270"><div class="more-goods-actions">
      <el-button v-if="refund.review_state==='APPROVED'&&refund.goods_state!=='DONE'&&(refund.platform.platform_status!=='CLOSED'||refund.funds_state==='SUCCESS')&&returnRequired&&!plans.length" v-hasPermi="['order:refund:close']" size="small" type="text" @click="open('waiveAll')">确认无需追回</el-button>
      <el-button v-if="refund.platform.platform_status==='CLOSED'&&refund.goods_state!=='DONE'&&refund.funds_state!=='SUCCESS'" v-hasPermi="['order:refund:close']" size="small" type="text" @click="open('closeWithdrawn')">确认申请关闭后的货物处置</el-button>
      <router-link :to="{path:'/oms-order/business',query:{view:'business',orderId:refund.order_id}}">原订单履约与截单</router-link><router-link :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'REFUND',number:refund.refund_sn,allTime:'true'}}">本退款仓库交互日志</router-link>
    </div><el-button slot="reference" size="small">更多处理</el-button></el-popover>
  </div>
  <refund-parcel-issue-review ref="issueReview" :refund="refund" @changed="parcelChanged" @waive="startParcelWaive"/>
  <div v-if="plans.length" class="refund-overview"><b>当前退款单 {{ refund.refund_sn }}</b><div class="refund-metrics"><div><span>计划退回</span><strong>{{ total('quantity') }} 件</strong></div><div><span>本退款实收</span><strong :class="{'warning':plans.some(planPending)}">{{ receiptText(total('accepted_quantity'),plans.some(planPending)) }}</strong></div><div><span>已入账</span><strong>{{ total('posted_quantity') }} 件</strong></div><div><span>不再追回</span><strong>{{ total('waived_quantity') }} 件</strong></div></div><p v-if="plans.some(planPending)" class="warning">关联包裹有实收待分配，尚不能确定本退款收到多少；查看包裹后按原回传分配。</p></div>
  <article v-for="b in bundleReturns" :key="b.id" class="plan"><h3>{{ b.business_type==='LUCKY_BAG'?'原袋退回':'整套退回' }} · {{ b.goods_name }} · {{ b.sku_sn }}</h3><p>应退 {{ b.quantity }} {{ b.business_type==='LUCKY_BAG'?'袋':'套' }} · 尚待退回／差异处理 {{ b.pending_quantity }} 件组件</p><el-alert v-if="b.pending_quantity" title="组件尚未退齐，已收组件按原来源入账；未收组件继续待退回，不自动结案。" type="warning" :closable="false"/><el-table :data="b.components" size="small"><el-table-column prop="sku_sn" label="组件SKU"/><el-table-column prop="quantity" label="应退件数"/><el-table-column prop="accepted_quantity" label="已确认实收"/><el-table-column prop="posted_quantity" label="已入账"/><el-table-column prop="remaining" label="待退回／差异处理"/></el-table><p v-if="b.components.some(c=>c.state==='NOT_CREATED')" class="warning">部分组件安排尚未创建，请用相同原袋 / 套数、退回仓和地址继续原退回流程。</p></article>
  <el-empty v-if="!plans.length" :description="returnRequired?'尚未安排退回，请明确实际发货来源和应退数量':'当前方案无需退回；未发商品取消请在原订单核对库存与截单结果'" :image-size="65" />
  <el-radio-group v-if="plans.some(p => Number(p.gift_plan_id) > 0)" v-model="planScope" size="small" class="plan-groups"><el-radio-button label="all">全部安排（{{ plans.length }}）</el-radio-button><el-radio-button label="purchase">购买商品（{{ purchasePlans.length }}）</el-radio-button><el-radio-button label="gift">赠品（{{ giftPlans.length }}）</el-radio-button></el-radio-group>
  <el-table v-if="visiblePlans.length" ref="planTable" :data="visiblePlans" row-key="id" size="small" class="return-plans-table">
    <el-table-column type="expand" width="38"><template slot-scope="{ row: p }">
  <article class="plan plan-expanded">
   <h4><el-tag v-if="p.gift_plan_id" size="mini" effect="plain">赠品</el-tag> {{ p.sku_sn }} · 退回安排 <el-tag size="mini">{{ planLabel(p.state) }}</el-tag></h4>
   <el-collapse><el-collapse-item title="退回来源、地址与处理依据" name="basis"><p class="hint">退回计划 #{{ p.id }} · 原发货单 {{ p.shipment_sn }} · 明细 #{{ p.shipment_line_id }} · {{ label(p.return_mode) }}<br>初始接收仓 {{ p.store_code }} · 初始寄回地址 {{ p.return_address }} · {{ p.return_contact }}<br>物流与运单在关联包裹的独立详情中管理 · 依据 {{ p.reason }} · 凭证 {{ p.evidence }}</p></el-collapse-item></el-collapse>
   <div class="totals">计划退回 <b>{{ p.quantity }}</b> · 本退款实收 <b>{{ receiptText(p.accepted_quantity,planPending(p)) }}</b> · 已入账 <b>{{ p.posted_quantity }}</b> · 不再追回 <b>{{ p.waived_quantity }}</b> · 尚未确认退回／差异处理 <b>{{ remaining(p) }}</b> 件</div>
   <el-alert v-if="pendingReviews(p).length" :title="`另有 ${pendingReviews(p).length} 条回传（${pendingQuantity(p)} 件）待人工核对，未计入实收和库存；请勿与待退回数量相加`" type="warning" show-icon :closable="false"/>
   <div v-if="sharedPlan(p)" class="toolbar"><span class="hint">本计划与关联退款共用THK；仓库原始回传、分配实收和共同截单统一在包裹详情处理。</span><el-button size="small" type="primary" @click="openParcel(p.id)">查看包裹及处理实收</el-button></div>
   <el-alert v-if="p.last_error" :title="p.last_error" type="warning" :closable="false" />
   <template v-if="!sharedPlan(p)">
   <p class="hint">下方是同一计划的逐次安排，旧单截停数量是当时的历史快照，不与新单数量相加。</p>
   <div v-if="activeDocuments(p).length" class="toolbar"><el-button v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="open('stop',p)">截停全部未完成安排（{{ activeDocuments(p).length }} 张）</el-button><span class="hint">仅停止本计划的后续收货，不撤销已实收入账；最终不再追回请另行处理差异。</span></div>
   <el-alert v-if="p.parcel_manual_dispatch&&p.state==='PLANNED'" title="已核对补充关联，下一步人工下发本退款退回单" description="原THK及已入账保留；新THK受理后再明确核对原包裹待分配实收，本次关联未增加库存。" type="info" :closable="false"/><div v-if="!p.actual" class="toolbar"><el-button v-if="p.state==='PLANNED'" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" type="primary" :disabled="parcelBlocked(p)" @click="command(p,null,'dispatch')">{{ p.parcel_manual_dispatch?'下发本退款补充退回单':'下发退回单至仓库' }}</el-button><el-button v-if="p.parcel_state==='NEED_CHECK'" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="$refs.issueReview.open(p.id)">先核对合包归属</el-button><el-button v-if="p.state==='PLANNED'" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="open('cancel',p)">停止本地安排</el-button><el-button v-if="p.state==='STOPPED'" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="open('rearrange',p)">重新安排</el-button></div>
   <div v-for="d in documents(p)" :key="d.id" class="document"><div class="heading"><router-link :to="{path:'/oms-supplychain/wmsTickets',query:{sn:d.return_sn,documentId:d.ticket_id}}"><strong>{{ d.return_sn }}</strong></router-link><el-tag size="mini">第 {{ d.generation }} 次安排 · {{ dispatch(d) }}</el-tag></div><p>本次安排 {{ d.quantity }} · 已确认实收 {{ d.accepted_quantity }} · 已入账 {{ d.posted_quantity }} 件 <span v-if="d.cancel_state!=='CONFIRMED'">· 本单待收 {{ Math.max(0,Number(d.quantity)-Number(d.accepted_quantity)) }} 件</span></p><p v-if="documents(p).length>1" class="hint">{{ d.id===documents(p)[0].id?'最新一次安排，是否继续执行以本单状态为准':'此前安排；后续另有新单，点击新单查看当前执行进度' }}</p><p class="hint">仓库单号 {{ d.external_order||'待返回' }} · 仓库状态 {{ d.warehouse_status||'待处理' }}<br>本次接收仓 {{ d.store_code }} · {{ d.return_address }}<br><span v-if="d.cancelled_at">截停时剩余 {{ d.cancelled_quantity }} 件（历史快照，不是当前计划待退数量）；{{ d.cancel_reason }}</span></p><el-alert v-if="d.last_error" :title="d.last_error" type="warning" :closable="false" /><div class="toolbar"><el-button v-if="d.dispatch_state==='PENDING'&&d.cancel_state==='NONE'&&(p.gift_plan_id||refund.goods_state!=='DONE')" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" type="primary" :disabled="pendingReviews(p).length>0||parcelBlocked(p)" @click="command(p,d,'dispatch')">下发本次退回单</el-button><el-button v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="command(p,d,'query')">查询仓库原单</el-button><el-button v-if="d.dispatch_state==='FAILED'&&d.cancel_state==='NONE'&&(p.gift_plan_id||refund.goods_state!=='DONE')" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" :disabled="pendingReviews(p).length>0||parcelBlocked(p)" @click="command(p,d,'retry')">重试下发</el-button><el-button v-if="Number(d.accepted_quantity)>Number(d.posted_quantity)" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="command(p,d,'posting')">重试原实收记账</el-button><el-button v-if="d.cancel_state!=='CONFIRMED'&&Number(d.accepted_quantity)<Number(d.quantity)&&(p.gift_plan_id||refund.goods_state!=='DONE')" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" @click="open('cancel',p,d)">截停本次安排剩余数量</el-button><el-button v-if="d.id===documents(p)[0].id&&d.cancel_state==='CONFIRMED'&&remaining(p)>0&&p.state!=='CLOSED'" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" size="small" :disabled="pendingReviews(p).length>0||parcelBlocked(p)" @click="open('rearrange',p,d)">重新安排剩余退回</el-button><router-link :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'DOCUMENT',number:d.return_sn,allTime:'true'}}">仓库交互日志</router-link></div></div>
   </template>
   <el-button v-if="remaining(p)>0&&p.state!=='CLOSED'&&(!p.gift_plan_id||$auth.hasPermiAnd(['order:refund:goods','order:gift:waive']))" v-hasPermi="['order:refund:close']" size="small" @click="open('waive',p)">剩余不再追回／差异处理</el-button>
   <template v-if="p.actual"><h4>已分配至本退款的逐次实收与入账</h4><p v-if="!(p.actual.lines||[]).length" class="hint">当前退款单尚无已确认实收；关联包裹待分配实收请进入包裹详情查看。</p><el-table v-if="(p.actual.lines||[]).length" :data="p.actual.lines||[]" empty-text="当前退款单尚无已确认实收；关联包裹待分配实收请进入包裹详情查看"><el-table-column prop="return_sn" label="退回单" min-width="280"/><el-table-column prop="message_id" label="回传消息" min-width="170"/><el-table-column label="SKU / 批次" min-width="180"><template slot-scope="s">{{ s.row.sku_sn }}<div class="hint">{{ s.row.batch_code }}</div></template></el-table-column><el-table-column label="本次良品 / 次品" width="140"><template slot-scope="s">{{ s.row.good_qty }} / {{ s.row.bad_qty }}</template></el-table-column><el-table-column label="记账" width="100"><template slot-scope="s">{{ Number(s.row.posted)?'已入账':'待入账' }}</template></el-table-column></el-table>
    <el-alert v-if="p.actual.parcel_pending_count" title="关联包裹存在实收待分配；本退款尚未确认的部分未入账，请进入包裹详情处理。" type="warning" :closable="false"/><h4 v-if="(p.actual.reviews||[]).length">异常回传 · 人工核对</h4><el-table v-if="(p.actual.reviews||[]).length" :data="p.actual.reviews"><el-table-column prop="return_sn" label="退回单" min-width="280"/><el-table-column prop="message_id" label="消息" min-width="170"/><el-table-column prop="quantity" label="本次数量" width="100"/><el-table-column label="结果" width="110"><template slot-scope="s">{{ ({WAIT_REVIEW:'待人工核对',ACCEPTED:'已确认实收',REJECTED:'已拒绝回传'})[s.row.state] }}</template></el-table-column><el-table-column prop="reason" label="原因 / 依据" min-width="200"/><el-table-column label="操作" width="95"><template slot-scope="s"><el-button v-if="s.row.state==='WAIT_REVIEW'" v-hasPermi="p.gift_plan_id ? ['order:gift:execute','order:refund:goods'] : ['order:refund:goods']" type="text" @click="open('review',p,documents(p).find(d=>Number(d.id)===Number(s.row.task_id)),s.row)">核对处理</el-button></template></el-table-column></el-table>
   </template>
  </article>
    </template></el-table-column>
    <el-table-column label="商品 / SKU" min-width="220"><template slot-scope="s"><strong>{{ s.row.sku_sn }}</strong><div class="hint">{{ s.row.gift_plan_id ? '本退款关联赠品' : '退款商品退回' }}</div></template></el-table-column>
    <el-table-column label="计划退回" width="100" align="right"><template slot-scope="s">{{ s.row.quantity }} 件</template></el-table-column>
    <el-table-column label="已确认实收" min-width="130" align="right"><template slot-scope="s">{{ receiptText(s.row.accepted_quantity, planPending(s.row)) }}</template></el-table-column>
    <el-table-column label="已入账" width="100" align="right"><template slot-scope="s">{{ s.row.posted_quantity }} 件</template></el-table-column>
    <el-table-column label="待退回" width="100" align="right"><template slot-scope="s">{{ remaining(s.row) }} 件</template></el-table-column>
    <el-table-column label="仓库下发" min-width="150"><template slot-scope="s"><span>{{ autoDispatchText(s.row) }}</span><div v-if="s.row.auto_dispatch_message" class="hint" :title="s.row.auto_dispatch_message">{{ s.row.auto_dispatch_message }}</div></template></el-table-column>
    <el-table-column label="进度" min-width="145"><template slot-scope="s">{{ planPending(s.row) ? '实收待分配' : planLabel(s.row.state) }}<div v-if="s.row.last_error" class="warning">{{ s.row.last_error }}</div><div v-if="pendingReviews(s.row).length" class="warning">回传待核对</div></template></el-table-column>
    <el-table-column label="操作" width="135"><template slot-scope="s"><el-button type="text" size="small" @click="$refs.planTable.toggleRowExpansion(s.row)">查看并处理</el-button></template></el-table-column>
  </el-table>
  <p v-else-if="plans.length" class="hint">{{ planScope === 'gift' ? '本退款暂无赠品退回安排' : '本退款暂无购买商品退回安排' }}</p>
  <refund-parcels ref="parcels" :refund="refund" :plans="plans" :active="active" @loaded="parcelRows=$event" @changed="parcelChanged" @review="plan=>$refs.issueReview.open(plan)"/>
  <el-dialog :title="titles[action]" :visible.sync="visible" width="min(780px,96vw)" append-to-body :close-on-click-modal="false"><el-alert :title="hint" type="info" :closable="false"/>
   <div v-if="action==='cancel'&&document" class="scope"><b>仅截停：{{ document.return_sn }}</b><p>本次未收 {{ Math.max(0,Number(document.quantity)-Number(document.accepted_quantity)) }} 件；保留已入账 {{ document.posted_quantity }} 件。</p><p>其他退回单继续执行。如需全部停止，请使用计划上的“截停全部未完成安排”。</p></div>
   <div v-if="action==='stop'" class="scope"><b>本计划将逐单申请截停：</b><p v-for="d in activeDocuments(selected)" :key="d.id">第 {{ d.generation }} 次 · {{ d.return_sn }} · 未收 {{ Math.max(0,Number(d.quantity)-Number(d.accepted_quantity)) }} 件</p><p>结果待确认或仓库拒绝时仍保留原安排，请查询核对；待核对回传不会自动接受或拒绝。</p></div>
   <div v-if="action==='review'" class="scope"><b>本次核对：{{ document&&document.return_sn }} · {{ reviewRow.quantity }} 件</b><p>计划 {{ selected.quantity }} 件 · 已确认实收 {{ selected.accepted_quantity }} 件 · 已入账 {{ selected.posted_quantity }} 件</p><p>若确认本次实收，预计仍需退回 {{ Math.max(0,remaining(selected)-Number(reviewRow.quantity||0)) }} 件；须先结束其他安排，确认后按原消息幂等入账，再按剩余量安排。</p><template v-if="activeDocuments(selected).length"><el-alert title="仍有安排在执行，暂不能确认迟到实收。请先截停并核对仓库结果，避免重复退回。" type="warning" :closable="false"/><p v-for="d in activeDocuments(selected)" :key="d.id">第 {{ d.generation }} 次 · {{ d.return_sn }} · 待收 {{ Math.max(0,Number(d.quantity)-Number(d.accepted_quantity)) }} 件</p><el-button size="small" @click="open('stop',selected)">先截停未完成安排</el-button></template><p v-if="form.decision==='REJECT'">拒绝仅表示本次回传不入账，不代表实物已退回或处置完成；请填写仓库核实结果与实物处置凭证。</p></div>
   <div v-if="action==='finish'" class="scope"><b>本次确认货物事项处理完成</b><p>计划合计 {{ total('quantity') }} 件 · 已入账 {{ total('posted_quantity') }} 件 · 不再追回 {{ total('waived_quantity') }} 件</p><el-alert v-if="finishBlockers.length" title="当前不能完成，请先处理以下事项" type="warning" :closable="false"/><p v-for="item in finishBlockers" :key="item">• {{ item }}</p><p v-if="!finishBlockers.length">数量已闭合，退回安排均已结束。请填写最终核对依据。</p><p>此操作不收货、不增加库存、不执行退款。{{ refund.funds_state==='SUCCESS'?'资金已成功，提交后退款单整体完成。':'资金尚未成功，提交后仍需等待资金结果。' }}</p></div>
   <el-form label-width="125px" style="margin-top:20px"><template v-if="action==='logistics'"><el-form-item label="退回运单" required><el-input v-model.trim="form.return_waybill" maxlength="128"/></el-form-item><el-form-item label="物流状态"><el-select v-model="form.transport_state"><el-option v-for="(v,k) in transportStates" :key="k" :value="k" :label="v"/></el-select></el-form-item></template><template v-if="action==='create'"><el-form-item v-if="(refund.bundles||[]).length" label="退回范围"><el-radio-group v-model="form.return_scope" @change="form.quantity=1"><el-radio label="COMPONENT">指定组件退回</el-radio><el-radio label="BUNDLE">原销售组合整袋 / 整套退回</el-radio></el-radio-group></el-form-item><el-form-item v-if="form.return_scope==='BUNDLE'" label="原销售商品" required><el-select v-model="form.bundle_id" @change="form.unit_ids=[];form.quantity=1"><el-option v-for="b in refund.bundles||[]" :key="b.id" :value="b.id" :label="`${b.sku_sn} · 购买${b.quantity}${b.business_type==='LUCKY_BAG'?'袋':'套'} · 原组成v${b.revision}`"/></el-select><p class="hint">按原组成与原批次展开退回。福袋需明确选择原袋，退款金额由审核方案决定。</p></el-form-item><el-form-item v-else label="实际发货来源" required><el-select v-model="form.shipment_line_id" style="width:100%"><el-option v-for="s in refund.shipments.filter(s=>Number(s.shipped_quantity)>0)" :key="s.shipment_line_id" :value="s.shipment_line_id" :label="`${s.shipment_sn} · #${s.shipment_line_id} · ${s.sku_sn} · 已出库${s.shipped_quantity}件`"/></el-select></el-form-item><el-form-item v-if="selectedLucky" label="选择原袋" required><el-checkbox-group v-model="form.unit_ids" @change="form.quantity=form.unit_ids.length"><div v-for="u in selectedBundle.units || []" :key="u.unit_id" class="scope"><el-checkbox :label="u.unit_id" :disabled="!!u.return_refund_id || !u.shipped_complete">第 {{ u.unit }} 袋 · #{{ u.unit_id }} · {{ u.return_refund_id ? '已安排整袋退回' : u.shipped_complete ? '整袋已发' : '尚未完整发出' }}</el-checkbox><div class="hint">{{ (u.components||[]).map(c=>`${c.sku_sn} × ${c.quantity || 1}件`).join('；') }}</div></div></el-checkbox-group><p class="hint">已选 {{ form.unit_ids.length }} 袋；已退组件的原袋请按实际可退组件处理。</p></el-form-item><el-form-item v-else :label="form.return_scope==='BUNDLE'?'本次应退套数':'本次应退件数'" required><el-input-number v-model="form.quantity" :min="1" :max="100000000" :precision="0"/></el-form-item></template><template v-if="['create','rearrange'].includes(action)"><el-form-item label="接收虚拟仓" required><el-select v-model="form.store_code" filterable><el-option v-for="w in warehouses" :key="w.code" :value="w.code" :label="`${w.name||w.code} (${w.code})`"/></el-select></el-form-item><el-form-item label="寄回地址" required><el-input v-model.trim="form.return_address" maxlength="500"/></el-form-item><el-form-item label="寄回联系信息" required><el-input v-model.trim="form.return_contact" maxlength="200"/></el-form-item></template><el-form-item v-if="action==='cancel'" label="截单目的"><el-radio-group v-model="form.mode"><el-radio label="WITHDRAW">撤回重新安排</el-radio><el-radio label="TERMINATE">终止剩余安排</el-radio></el-radio-group></el-form-item><el-form-item v-if="action==='review'" label="核对结论"><el-radio-group v-model="form.decision"><el-radio label="REJECT">拒绝本次回传</el-radio><el-radio label="ACCEPT" :disabled="activeDocuments(selected).length>0">确认真实实收</el-radio></el-radio-group></el-form-item><el-form-item v-if="action==='waive'" label="未追回数量">{{ remaining(selected) }} 件；不会增加库存</el-form-item><el-form-item label="处理依据" required><el-input v-model.trim="form.reason" type="textarea" :maxlength="action==='review'?200:500"/></el-form-item><el-form-item label="核对凭证" required><el-input v-model.trim="form.evidence" type="textarea" :maxlength="action==='review'?250:1000"/></el-form-item><el-form-item><el-checkbox v-model="form.confirmed">已核对实际商品、处理范围、数量与凭证</el-checkbox></el-form-item></el-form><span slot="footer"><el-button @click="visible=false">返回</el-button><el-button type="primary" :loading="busy" :disabled="!form.confirmed||(action==='finish'&&finishBlockers.length>0)||(action==='review'&&form.decision==='ACCEPT'&&activeDocuments(selected).length>0)" @click="submit">确认提交</el-button></span></el-dialog>
 </section>
</template>
<script>
import * as api from '@/api/order/refund'
import { autoDispatchText } from './returnRulePresentation'
import { giftReturnAction, giftReturnOptions } from '@/api/order/gift'
import RefundParcels from './RefundParcels'
import RefundParcelIssueReview from './RefundParcelIssueReview'
import { label } from './refundLabels'
import { receiptText, sourcePending, allocationOutcome } from './refundParcelPresentation'
import { documents, activeDocuments, pendingReviews, pendingQuantity, remaining, completionBlockers } from './refundGoodsPresentation'
export default {name:'RefundGoods',components:{RefundParcels,RefundParcelIssueReview},props:{refund:{type:Object,required:true},active:{type:Boolean,default:true}},data:()=>({loading:false,busy:false,error:'',planScope:'all',dirty:false,plans:[],bundleReturns:[],parcelRows:[],sequence:0,visible:false,action:'',selected:{},document:null,reviewRow:{},form:{},warehouses:[],transportStates:{WAITING:'待退回',IN_TRANSIT:'退回在途',REFUSED:'已拒收待退回',INTERCEPTED:'已拦截待退回',DELIVERED:'物流已签收（非仓库实收）'},titles:{logistics:'登记退回物流',cancelUnshipped:'执行已审核的未发取消',create:'创建退款退回安排',cancel:'截停本次安排剩余数量',stop:'截停本计划全部未完成安排',rearrange:'重新安排剩余退回',review:'核对异常实收',waive:'剩余不再追回',waiveAll:'确认无需追回',finish:'确认货物处理完成',closeWithdrawn:'确认申请关闭后的货物处置'}}),computed:{selectedBundle(){return (this.refund.bundles||[]).find(b=>Number(b.id)===Number(this.form.bundle_id))||{}},selectedLucky(){return this.form.return_scope==='BUNDLE'&&this.selectedBundle.business_type==='LUCKY_BAG'},autoCreateTitle(){return ({PENDING:'正在自动创建商品退回安排',RETRY:'自动创建稍后重试',MANUAL:'商品退回安排需人工核对',CANCELED:'自动创建商品退回安排已暂停',DONE:'自动创建处理结果'})[(this.refund.return_auto||{}).state]||'商品退回安排'},purchasePlans(){return this.plans.filter(p=>!Number(p.gift_plan_id))},giftPlans(){return this.plans.filter(p=>Number(p.gift_plan_id)>0)},visiblePlans(){return this.planScope==='gift'?this.giftPlans:this.planScope==='purchase'?this.purchasePlans:this.plans},finishBlockers(){return completionBlockers(this.plans)},returnRequired(){return ['REFUSAL','INTERCEPT','RETURN'].includes(this.refund.goods_action)},hint(){return this.action==='review'?'先核实仓库实物与原消息。确认迟到实收前须截停其他安排；拒绝回传不代表实物已经处理。':['waive','waiveAll'].includes(this.action)?'此操作仅记录不再追回的依据，不伪造收货、不增加库存。已有仓库安排必须先确认截停。':this.action==='closeWithdrawn'?'仅结束平台已关闭申请的货物事项。必须先结束所有仓库安排、完成实收入账及待核对回传；已入账库存保留，剩余终止追回，必须填写实物处置凭证。':this.action==='finish'?'这是退款货物事项的最终确认，不是仓库收货或质检操作；所有未完成事项处理后才能提交。':'按实际发货明细安排。创建及下发不会增加库存；截单只停止仓库剩余收货，不代表已拦截物流。'}},watch:{refund(){if(this.active)this.load();else this.dirty=true},active(value){if(value&&this.dirty){this.dirty=false;this.load()}}},created(){if(this.active)this.load();else this.dirty=true},beforeDestroy(){this.sequence++},methods:{autoDispatchText,async retryAutoCreate(){if(this.busy)return;this.busy=true;try{await api.retryRefundAutoCreate(this.refund.id,{control_version:this.refund.control_version});this.$message.success('已提交重新检查');this.$emit('changed')}finally{this.busy=false}},receiptText,openIssue(id){this.$refs.issueReview.open(id)},
planOutcome(p){const parcel=this.parcelRows.find(parcel=>(parcel.members||[]).some(m=>Number(m.plan_id)===Number(p.id)));return parcel?allocationOutcome(parcel,p.id):''},
planPending(p){return Number((p.actual||{}).parcel_pending_count)>0||this.parcelRows.some(parcel=>(parcel.members||[]).some(m=>Number(m.plan_id)===Number(p.id)&&sourcePending(parcel,m)))},
sharedPlan(p){return p.parcel_state==='LINKED'||!!(p.actual&&p.actual.shared_document)},
openParcel(plan){return this.$refs.parcels.openForPlan(plan)},
openParcels(){return this.$refs.parcels.openFirst()},
parcelBlocked(p){return p.parcel_state==='NEED_CHECK'||['WAIT_BUYER','WAREHOUSE_CHECK'].includes(p.parcel_resolution)},async startParcelWaive(id){await this.load();const p=this.plans.find(p=>Number(p.id)===Number(id));if(p)this.open('waive',p);else this.$message.warning('退回计划已变化，请刷新核对')},async parcelChanged(){await this.refresh()},label,remaining,activeDocuments,pendingReviews,pendingQuantity,total(key){return this.plans.reduce((n,p)=>n+Number(p[key]||0),0)},planLabel(s){return ({PLANNED:'待下发',ACTIVE:'待仓库收货',PARTIAL:'部分实收',STOPPED:'安排已结束',WAIT_REVIEW:'待人工核对',CLOSED:'已处理'})[s]||s},documents,dispatch(d){return d.cancel_state==='CONFIRMED'?'剩余已截停':({PENDING:'待下发',SENDING:'下发中',ACCEPTED:'仓库已接收',UNKNOWN:'结果待确认',FAILED:'下发失败',CANCELED:'安排已停止'})[d.dispatch_state]||d.dispatch_state},async load(){const seq=++this.sequence;this.loading=true;try{const r=(await api.refundGoods(this.refund.id)).data;if(seq===this.sequence){this.plans=r.plans;this.bundleReturns=r.bundle_returns||[];this.error=''}}catch(_){if(seq===this.sequence)this.error='退回安排加载失败，请刷新核对'}finally{if(seq===this.sequence)this.loading=false}},async refresh(){if(this.busy)return;this.busy=true;try{await api.refreshRefundGoods(this.refund.id);this.$emit('changed')}finally{this.busy=false}},async open(action,p={},d=null,review=null){if(p.actual&&p.actual.shared_document&&['cancel','stop','rearrange'].includes(action))return this.$message.warning('这是共同THK，请在退回包裹中确认整单影响后操作');this.action=action;this.selected=p;this.document=d;this.reviewRow=review||{};this.form={request_key:'RET_'+Date.now()+'_'+Math.random().toString(16).slice(2),return_scope:'COMPONENT',unit_ids:[],bundle_id:(this.refund.bundles||[])[0]&&this.refund.bundles[0].id,quantity:action==='waive'?this.remaining(p):1,shipment_line_id:undefined,store_code:d&&d.store_code||p.store_code||'',return_address:d&&d.return_address||p.return_address||'',return_contact:d&&d.return_contact||p.return_contact||'',return_waybill:p.return_waybill||'',transport_state:p.transport_state||'WAITING',reason:'',evidence:'',mode:'WITHDRAW',decision:'REJECT',review_id:review&&review.id,confirmed:false};if(['create','rearrange'].includes(action))this.warehouses=(await (p.gift_plan_id?giftReturnOptions:api.refundGoodsOptions)(this.refund.id)).data.warehouses;this.visible=true},async command(p,d,action,body={}){if((p.actual&&p.actual.shared_document&&['cancel','rearrange','stop','retry','dispatch'].includes(action))||(!p.actual&&p.parcel_state==='LINKED'&&action==='dispatch'))return this.$message.warning('请到上方退回包裹核对全部退款并统一处理共同THK');if(this.busy)return;this.busy=true;try{await (p.gift_plan_id&&action!=='waive'&&this.$auth.hasPermi('order:gift:execute')?giftReturnAction:api.refundGoodsAction)(this.refund.id,p.id,d&&d.id||0,action,{...body,control_version:this.refund.control_version,plan_version:p.control_version,document_version:d&&d.control_version});this.visible=false;this.$emit('changed')}finally{this.busy=false}},async submit(){if(this.action==='create'&&this.selectedLucky&&!this.form.unit_ids.length)return this.$message.warning('请选择本次退回的原袋');if(!this.form.reason||!this.form.evidence)return this.$message.warning('请填写处理依据和核对凭证');if(this.action==='create'||['finish','waiveAll','cancelUnshipped','closeWithdrawn'].includes(this.action)){if(this.busy)return;this.busy=true;try{const fn=this.action==='create'?(this.form.return_scope==='BUNDLE'?api.createRefundBundleReturn:api.createRefundReturn):this.action==='cancelUnshipped'?api.cancelRefundUnshipped:this.action==='finish'?api.finishRefundGoods:this.action==='closeWithdrawn'?api.closeWithdrawnRefund:api.waiveRefundGoods;await fn(this.refund.id,{...this.form,control_version:this.refund.control_version});this.visible=false;this.$emit('changed')}finally{this.busy=false}}else return this.command(this.selected,this.document,this.action,{...this.form,...(this.action==='rearrange'?{quantity:this.remaining(this.selected)}:{})})}}}
</script>
<style scoped>.return-plans-table{margin:12px 0 24px}.plan-expanded{margin:0;border:0;padding:12px 18px;background:#f8fafc}.more-goods-actions{display:flex;align-items:flex-start;flex-direction:column;gap:12px;font-size:13px}.more-goods-actions .el-button{margin:0}.plan-groups{margin:16px 0}.plan h4{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.refund-goods{margin:24px 0}.heading,.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.heading{justify-content:space-between}.hint{font-size:12px;color:#8290a4;line-height:1.8}.toolbar{margin:16px 0}.toolbar .el-button{margin:0}.toolbar a,.heading a{color:#1677ff;font-size:13px}.plan{padding:20px;border:1px solid #e1e8f0;border-radius:8px;margin:18px 0}.totals{padding:16px;background:#f4f7fc;border-radius:6px;color:#61728a}.totals b{color:#263c57}.document{padding:16px;border:1px solid #edf0f5;margin:16px 0}.scope{padding:14px 18px;background:#f4f7fc;border-radius:6px;overflow-wrap:anywhere;line-height:1.8;margin:14px 0}.el-select{width:100%}.el-alert{margin:12px 0}h3,h4{margin:12px 0}.refund-overview{background:#f4f7fc;border-radius:8px;padding:18px;margin:18px 0;overflow-wrap:anywhere}.refund-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:16px}.refund-metrics span{display:block;color:#61728a;font-size:12px}.refund-metrics strong{display:block;margin-top:8px;font-size:18px}.warning{color:#a46808;line-height:1.8}@media(max-width:760px){.refund-metrics{grid-template-columns:repeat(2,1fr)}}
</style>
